        yield (self.foo,)
        yield None, self.foo,
        yield "bar", self.bar, None
        yield "egg", self.egg

    __rich_repr__.angular = True

class StupidClass:
    def __init__(self, a):
        self.a = a

    def __eq__(self, other) -> bool:
        if other is Parameter.empty:
            return True
        try:
            return self.a == other.a
        except Exception:
            return False

    def __ne__(self, other: object) -> bool:
        return not self.__eq__(other)

def __eq__(self, other) -> bool:
    if other is Parameter.empty:
        return True
    try:
        return self.a == other.a
    except Exception:
        return False

@rich.repr.auto
class Bird:
    def __init__(
